import React, { useState } from 'react';
import { Task, TomorrowPlan } from '../types';

interface NightReviewProps {
  tasks: Task[];
  tomorrowPlan: TomorrowPlan;
  setTomorrowPlan: (plan: TomorrowPlan) => void;
  onComplete: () => void;
  onClose: () => void;
  darkMode: boolean;
}

const NightReview: React.FC<NightReviewProps> = ({
  tasks,
  tomorrowPlan,
  setTomorrowPlan,
  onComplete,
  onClose,
  darkMode
}) => {
  const [showSubmitPopup, setShowSubmitPopup] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  const calculatePoints = () => {
    let totalPoints = 0;

    tasks.forEach(task => {
      if (task.completed) {
        if (task.category === 'Trading') totalPoints += 10;
        else if (task.category === 'Flutter/React') totalPoints += 10;
        else if (task.category === 'Coding/DSA') totalPoints += 8;
        else if (task.category === 'Morning Routine') totalPoints += 5;
        else if (task.category === 'Night Review') totalPoints += 5;
        else totalPoints += 3;
      } else if (task.skipped) {
        if (task.category === 'Trading') totalPoints -= 10;
        else if (task.category === 'Flutter/React') totalPoints -= 10;
        else if (task.category === 'Coding/DSA') totalPoints -= 8;
        else if (task.category === 'Morning Routine') totalPoints -= 5;
        else if (task.category === 'Night Review') totalPoints -= 5;
        else totalPoints -= 3;
      }
    });

    const allCompleted = tasks.every(task => task.completed);
    if (allCompleted) totalPoints += 20;

    const allMissed = tasks.every(task => !task.completed);
    if (allMissed) totalPoints -= 30;

    return totalPoints;
  };

  const calculateGrade = () => {
    const completedTasks = tasks.filter(t => t.completed).length;
    const totalTasks = tasks.length;
    const percentage = (completedTasks / totalTasks) * 100;

    if (percentage >= 90) return 'A';
    if (percentage >= 80) return 'B';
    if (percentage >= 70) return 'C';
    if (percentage >= 60) return 'D';
    return 'F';
  };

  const handleSubmit = () => {
    const allTasksReviewed = tasks.every(task => task.completed || task.skipped);
    const hasTomorrowPlan = tomorrowPlan.englishTopic || tomorrowPlan.tradingStrategy || tomorrowPlan.dsaTopic || tomorrowPlan.flutterReactChapter;

    if (!allTasksReviewed) {
      alert('Please mark all tasks as Completed or Skipped before submitting!');
      return;
    }

    if (!hasTomorrowPlan) {
      alert('Please fill in tomorrow\'s plan before submitting!');
      return;
    }

    // Show popup and submit
    setShowSubmitPopup(true);
    setIsSubmitted(true);
    onComplete();
  };

  const getPerformanceMessage = () => {
    const completedTasks = tasks.filter(t => t.completed).length;
    const totalTasks = tasks.length;
    const percentage = (completedTasks / totalTasks) * 100;

    if (percentage === 100) return "🎉 Perfect Day! All tasks completed!";
    if (percentage >= 75) return "👏 Great job! Most tasks completed!";
    if (percentage >= 50) return "💪 Good effort! Half way there!";
    return "📚 Keep trying! Tomorrow is a new day!";
  };

  if (isSubmitted) {
    return (
      <div className="fixed inset-0 bg-black bg-opacity-90 flex items-center justify-center z-50">
        <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-8 max-w-md mx-4`}>
          <div className="text-center">
            <div className="text-6xl mb-4">🌙</div>
            <h2 className="text-2xl font-bold text-white mb-4">Good Night!</h2>
            <p className="text-lg text-white mb-6">
              Today's review has been submitted. See you tomorrow!
            </p>
            <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} rounded-lg p-4 mb-6`}>
              <h3 className="font-semibold text-white mb-2">Tomorrow's Preview:</h3>
              <div className="space-y-2 text-sm">
                {tomorrowPlan.englishTopic && (
                  <div className="text-white">📚 English: {tomorrowPlan.englishTopic}</div>
                )}
                {tomorrowPlan.tradingStrategy && (
                  <div className="text-white">💰 Trading: {tomorrowPlan.tradingStrategy}</div>
                )}
                {tomorrowPlan.dsaTopic && (
                  <div className="text-white">💻 Coding: {tomorrowPlan.dsaTopic}</div>
                )}
                {tomorrowPlan.flutterReactChapter && (
                  <div className="text-white">📱 Development: {tomorrowPlan.flutterReactChapter}</div>
                )}
              </div>
            </div>
            <div className="text-blue-400 text-sm">
              Rest well and be ready for tomorrow's challenges!
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      {showSubmitPopup && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50">
          <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-6 max-w-sm mx-4`}>
            <h3 className="text-lg font-bold text-white mb-4">{getPerformanceMessage()}</h3>
            <div className="space-y-3 mb-4">
              <div className="flex justify-between">
                <span className="text-white">Today's Score:</span>
                <span className="text-xl font-bold text-yellow-400">{calculatePoints()} points</span>
              </div>
              <div className="flex justify-between">
                <span className="text-white">Performance Grade:</span>
                <span className="text-xl font-bold text-blue-400">{calculateGrade()}</span>
              </div>
            </div>
            <button
              onClick={() => setShowSubmitPopup(false)}
              className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors"
            >
              Got it!
            </button>
          </div>
        </div>
      )}

      <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-8 max-w-2xl w-full mx-4 max-h-screen overflow-y-auto`}>
        <h2 className="text-2xl font-bold text-white mb-6">Night Review & Next Day Planner</h2>

        {/* Today's Review */}
        <div className="mb-8">
          <h3 className="text-lg font-semibold text-white mb-4">Today's Performance</h3>
          <div className="space-y-2 mb-4">
            {tasks.map(task => (
              <div key={task.id} className={`flex items-center justify-between p-3 rounded ${darkMode ? 'bg-dark-primary' : 'bg-gray-50'}`}>
                <span className="text-white">{task.title}</span>
                <div className="flex items-center space-x-2">
                  <button
                    onClick={() => {
                      // This would be handled by parent component
                      console.log('Task status change');
                    }}
                    className={`px-3 py-1 rounded text-sm font-medium ${
                      task.completed ? 'bg-green-600 text-white' : 
                      task.skipped ? 'bg-yellow-600 text-white' : 
                      'bg-gray-600 text-white'
                    }`}
                  >
                    {task.completed ? '✓ Completed' : task.skipped ? '⊘ Skipped' : '○ Pending'}
                  </button>
                </div>
              </div>
            ))}
          </div>

          <div className="grid grid-cols-2 gap-4 mb-6">
            <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} p-4 rounded-lg`}>
              <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Today's Score</div>
              <div className="text-2xl font-bold text-yellow-400">{calculatePoints()} points</div>
            </div>
            <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} p-4 rounded-lg`}>
              <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Performance Grade</div>
              <div className="text-2xl font-bold text-blue-400">{calculateGrade()}</div>
            </div>
          </div>
        </div>

        {/* Tomorrow's Plan */}
        <div className="mb-6">
          <h3 className="text-lg font-semibold text-white mb-4">Plan Tomorrow</h3>
          <div className="space-y-4">
            <div>
              <label className={`block text-sm font-medium ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'} mb-2`}>
                English Practice Topic
              </label>
              <input
                type="text"
                value={tomorrowPlan.englishTopic}
                onChange={(e) => setTomorrowPlan({...tomorrowPlan, englishTopic: e.target.value})}
                className={`w-full px-4 py-2 rounded-lg ${darkMode ? 'bg-dark-primary text-white border-dark-accent' : 'bg-white text-gray-900 border-gray-300'} border focus:ring-2 focus:ring-blue-500 focus:border-transparent`}
                placeholder="e.g., Business English vocabulary"
              />
            </div>

            <div>
              <label className={`block text-sm font-medium ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'} mb-2`}>
                Trading Strategy
              </label>
              <input
                type="text"
                value={tomorrowPlan.tradingStrategy}
                onChange={(e) => setTomorrowPlan({...tomorrowPlan, tradingStrategy: e.target.value})}
                className={`w-full px-4 py-2 rounded-lg ${darkMode ? 'bg-dark-primary text-white border-dark-accent' : 'bg-white text-gray-900 border-gray-300'} border focus:ring-2 focus:ring-blue-500 focus:border-transparent`}
                placeholder="e.g., Focus on support/resistance levels"
              />
            </div>

            <div>
              <label className={`block text-sm font-medium ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'} mb-2`}>
                DSA Topic/Question Set
              </label>
              <input
                type="text"
                value={tomorrowPlan.dsaTopic}
                onChange={(e) => setTomorrowPlan({...tomorrowPlan, dsaTopic: e.target.value})}
                className={`w-full px-4 py-2 rounded-lg ${darkMode ? 'bg-dark-primary text-white border-dark-accent' : 'bg-white text-gray-900 border-gray-300'} border focus:ring-2 focus:ring-blue-500 focus:border-transparent`}
                placeholder="e.g., Dynamic programming - Knapsack problems"
              />
            </div>

            <div>
              <label className={`block text-sm font-medium ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'} mb-2`}>
                Flutter/React Chapter/Feature
              </label>
              <input
                type="text"
                value={tomorrowPlan.flutterReactChapter}
                onChange={(e) => setTomorrowPlan({...tomorrowPlan, flutterReactChapter: e.target.value})}
                className={`w-full px-4 py-2 rounded-lg ${darkMode ? 'bg-dark-primary text-white border-dark-accent' : 'bg-white text-gray-900 border-gray-300'} border focus:ring-2 focus:ring-blue-500 focus:border-transparent`}
                placeholder="e.g., Flutter widgets - State management"
              />
            </div>
          </div>
        </div>

        <div className="flex justify-end space-x-4">
          <button
            onClick={onClose}
            className={`px-6 py-2 ${darkMode ? 'bg-dark-accent hover:bg-dark-muted' : 'bg-gray-200 hover:bg-gray-300'} rounded-lg transition-colors`}
          >
            Cancel
          </button>
          <button
            onClick={handleSubmit}
            className="px-6 py-2 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white rounded-lg transition-colors"
          >
            Submit & Lock Day
          </button>
        </div>
      </div>
    </div>
  );
};

export default NightReview;
